<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useStudio,time} from './studio'
const studio=useStudio()
const {view,settings,error,notice,draft,dirty,consentA,consentD,limitation,narrative,selectedTrack,selectedSpeaker,id,state,busy,speakers,flags,original}=studio
const page=ref(location.hash==='#settings'?'settings':'document')
const theme=ref<'light'|'dark'>(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')
watch(theme,value=>document.documentElement.dataset.theme=value,{immediate:true})
const tab=ref('original'),keyA=ref(''),keyD=ref(''),revealA=ref(false),revealD=ref(false)
watch(page,value=>{location.hash=value==='settings'?'settings':'';keyA.value='';keyD.value='';revealA.value=false;revealD.value=false})
const file=computed(()=>view.value?.Document.File.split(/[\\/]/).pop()??'Nenhum arquivo selecionado')
const stage=computed(()=>({empty:0,awaiting_track:0,awaiting_consent:0,transcribing:1,awaiting_speaker:2,awaiting_review_consent:3,reviewing:3,ready:3,failed:3,cancelled:0}[state.value]??0))
const title=computed(()=>({empty:'Cada palavra, com o devido cuidado.',awaiting_track:'Escolha a trilha de áudio',awaiting_consent:'Antes de transcrever',transcribing:'Transcrição em andamento',awaiting_speaker:'Identifique quem presta o depoimento',awaiting_review_consent:'Prepare a proposta de revisão',reviewing:'Revisão em andamento',ready:'Compare e aperfeiçoe o depoimento',failed:'A revisão precisa ser repetida',cancelled:'Processamento cancelado'}[state.value]??'Seu depoimento'))
const preview=import.meta.env.DEV && new URLSearchParams(location.search).has('preview')
async function saveA(){const key=keyA.value;keyA.value='';revealA.value=false;await studio.saveKey('assemblyai',key)}
async function saveD(){const key=keyD.value;keyD.value='';revealD.value=false;await studio.saveKey('deepseek',key)}
function navigate(value:string){page.value=value}
</script>

<template>
 <a class="skip-link" href="#main">Ir ao documento</a>
 <div v-if="preview" class="preview-banner">Prévia de desenvolvimento · dados fictícios · sem chamadas a provedores</div>
 <div class="shell">
  <div class="brand"><svg viewBox="0 0 28 32" aria-hidden="true"><path d="M3 14v4m5-9v14m6-21v28m6-20v12m5-8v4"/></svg><span>Depoimento Studio</span></div>
  <header class="header"><div class="breadcrumbs"><span>Espaço de trabalho</span><span aria-hidden="true">›</span><strong>{{page==='settings'?'Configurações':'Revisão de depoimento'}}</strong></div><div class="top-actions"><button class="pill" @click="theme=theme==='light'?'dark':'light'">{{theme==='light'?'Tema escuro':'Tema claro'}}</button><button class="pill dark" @click="navigate(page==='settings'?'document':'settings')">{{page==='settings'?'Voltar ao documento':'Configurações'}}</button></div></header>
  <aside class="sidebar"><nav class="navigation" aria-label="Navegação principal"><button :class="{selected:page==='document'}" @click="navigate('document')"><span aria-hidden="true">▤</span> Depoimento</button><button :class="{selected:page==='settings'}" @click="navigate('settings')"><span aria-hidden="true">⚙</span> Configurações</button></nav><div class="profile"><div><p>Uma sessão. Um arquivo.</p><small>Conteúdo mantido em memória.<br>Exporte antes de encerrar.</small></div></div></aside>
  <main id="main" class="workspace" :class="{'settings-workspace':page==='settings'}" tabindex="-1">
   <div class="main">
    <div v-if="error || view?.Error" class="feedback error" role="alert">{{error||view?.Error}}</div>
    <div v-if="notice" class="feedback success" role="status">{{notice}}</div>
    <template v-if="page==='document'">
     <p class="status"><span class="dot"/>{{busy?'Processamento em andamento':state==='ready'?'Proposta disponível para conferência':'Seu espaço de revisão'}}</p>
     <h1>{{title}}</h1><p class="intro">O original permanece intacto. Revise a proposta com apoio do áudio e preserve o que foi efetivamente dito.</p>
     <ol class="steps" aria-label="Etapas do processamento"><template v-for="(label,index) in ['Arquivo','Transcrição','Falantes','Revisão']" :key="label"><li class="step" :class="{active:stage===index}" :aria-current="stage===index?'step':undefined"><i>{{index+1}}</i>{{label}}</li><span v-if="index<3" class="connector" aria-hidden="true"/></template></ol>
     <section v-if="state==='empty' || state==='cancelled'" class="upload-panel">
      <img src="/design/audio-folder.png" alt="" width="160" height="120"><h2>Selecione um áudio ou vídeo</h2><p>Trabalhe em um único arquivo, da transcrição à revisão.</p><button class="button primary" :disabled="busy" @click="studio.selectFile">Escolher arquivo</button><p class="muted">MP3, WAV, M4A, MP4, MKV, MOV, OGG, FLAC, WEBM e AAC.</p>
     </section>
     <section v-if="id" class="file-strip"><div><strong>{{file}}</strong><small>Arquivo original · {{view?.Tracks?.length??0}} trilha(s) de áudio</small></div><button class="button" :disabled="busy" @click="studio.selectFile">Trocar arquivo</button></section>
     <section v-if="state==='awaiting_track'" class="panel"><h2>Há mais de uma trilha de áudio</h2><p>Escolha qual trilha contém o depoimento. Nenhuma será escolhida automaticamente.</p><label for="track">Trilha</label><select id="track" v-model.number="selectedTrack"><option v-for="track in view?.Tracks" :key="track.index" :value="track.index">{{track.index}} · {{track.tags.language||'idioma não informado'}} · {{track.channels}} canal(is) · {{track.codec_name}} {{track.tags.title}}</option></select><button class="button primary" :disabled="busy" @click="studio.selectTrack">Confirmar trilha</button></section>
     <section v-if="state==='awaiting_consent'" class="panel"><p class="eyebrow">ASSEMBLYAI · ENVIO DO ÁUDIO</p><h2>Autorize este arquivo</h2><p>O áudio será enviado à AssemblyAI para transcrição e separação de falantes. Retenção e uso dependem das condições da sua conta.</p><label class="check-row"><input v-model="consentA" type="checkbox">Confirmo que tenho autorização aplicável para enviar este arquivo à AssemblyAI.</label><div class="warning"><strong>Hesitações em português</strong><p>O suporte documentado de <code>disfluencies</code> é apenas em inglês. Hesitações, repetições e palavras podem se perder na transcrição em português.</p></div><label class="check-row"><input v-model="limitation" type="checkbox">Entendo essa limitação e vou conferir a transcrição ouvindo o áudio original.</label><p v-if="!settings.AssemblyAIConfigured" class="warning">Configure a API Key da AssemblyAI antes de continuar.</p><button class="button primary" :disabled="busy||!consentA||!limitation||!settings.AssemblyAIConfigured" @click="studio.transcribe">Autorizar e transcrever</button></section>
     <section v-if="view?.Busy" class="panel processing" aria-live="polite"><div class="pulse" aria-hidden="true"/><h2>{{state==='reviewing'?'Preparando a proposta':'Processando o áudio'}}</h2><p>O tempo depende da duração da mídia e do provedor. Você pode cancelar o processamento local.</p><button class="button" @click="studio.cancel" :disabled="studio.pending.value">Cancelar processamento</button></section>
     <section v-if="state==='awaiting_speaker'" class="panel"><h2>Quem é o depoente?</h2><p>Leia os trechos e confira o áudio no seu reprodutor antes de escolher. As letras são rótulos automáticos.</p><fieldset><legend>Selecione o depoente</legend><label v-for="speaker in speakers" :key="speaker" class="speaker-choice"><input v-model="selectedSpeaker" type="radio" name="speaker" :value="speaker"><span><strong>Falante {{speaker}}</strong><span>{{view?.Document.Original.utterances?.find(u=>u.speaker===speaker)?.text}}</span></span></label></fieldset><button class="button primary" :disabled="busy||!selectedSpeaker" @click="studio.identify">Confirmar depoente</button></section>
     <section v-if="state==='awaiting_review_consent'" class="panel"><p class="eyebrow">DEEPSEEK · ENVIO DA TRANSCRIÇÃO</p><h2>Escolha como apresentar o texto</h2><p>Depoente confirmado: falante {{view?.Document.Speaker}}. Modelo: {{settings.Model}}.</p><fieldset><legend>Formato da proposta</legend><label class="check-row"><input v-model="narrative" type="radio" :value="false" name="format">Diálogo — perguntas e respostas separadas</label><label class="check-row"><input v-model="narrative" type="radio" :value="true" name="format">Narrativa — somente falas do depoente, sem completar respostas com perguntas</label></fieldset><label class="check-row"><input v-model="consentD" type="checkbox">Confirmo que tenho autorização aplicável para enviar esta transcrição à DeepSeek.</label><p class="muted">A política pública não assegura condições específicas da API para conteúdo sigiloso. Confira as condições aplicáveis antes de autorizar.</p><p v-if="!settings.DeepSeekConfigured" class="warning">Configure a API Key da DeepSeek antes de continuar.</p><button class="button primary" :disabled="busy||!consentD||!settings.DeepSeekConfigured" @click="studio.review">Autorizar e revisar</button></section>
     <section v-if="state==='failed'" class="panel"><h2>O original está disponível</h2><p>A revisão incompleta não foi publicada. Repetir a revisão não refaz a transcrição; uma nova chamada poderá ser cobrada.</p><button class="button primary" :disabled="busy" @click="studio.retry">Preparar nova tentativa de revisão</button></section>
     <div v-if="original" class="comparison-wrap"><div class="document-tabs" role="tablist" aria-label="Documentos"><button id="tab-original" role="tab" :aria-selected="tab==='original'" :tabindex="tab==='original'?0:-1" @keydown.right="tab='proposal'" @click="tab='original'">Original</button><button id="tab-proposal" role="tab" :aria-selected="tab==='proposal'" :tabindex="tab==='proposal'?0:-1" @keydown.left="tab='original'" @click="tab='proposal'">Proposta</button></div><div class="comparison" :data-tab="tab"><section class="recording original" aria-label="Transcrição original"><div class="card-head"><span class="badge">Original</span><span class="immutable">Imutável</span></div><pre class="transcript">{{original}}</pre><div class="card-foot">Transcrição automática · confira com o áudio</div></section><section class="recording proposal" aria-label="Proposta revisada"><div class="card-head"><span class="badge">Proposta</span><span class="editable">{{dirty||view?.Document.HasEdits?'Edição humana':'Editável'}}</span></div><label class="sr-only" for="proposal">Proposta editável</label><textarea id="proposal" :value="draft" :disabled="state!=='ready'" :placeholder="state==='ready'?'Proposta vazia':'A proposta aparecerá após a revisão.'" @input="studio.edit(($event.target as HTMLTextAreaElement).value)"/><div class="card-foot">{{state==='ready'?'Edições usadas ao copiar e exportar':'Aguardando a etapa de revisão'}}</div></section></div></div>
     <section v-if="flags.length" class="panel flags"><h2>{{flags.length}} trecho(s) exigem atenção</h2><p>Alertas heurísticos não certificam equivalência semântica. Confira o áudio e corrija a proposta quando necessário.</p><details v-for="change in flags" :key="change.id"><summary>{{change.id}} · {{change.flags?.join('; ')}}</summary><p><strong>Original:</strong> {{change.original}}</p><p><strong>Proposta:</strong> {{change.revised}}</p></details></section>
     <div v-if="state==='ready'" class="notice">A proposta é uma sugestão. Confira atribuições, números, datas, negativas e incertezas antes de utilizar o texto.</div>
    </template>
    <section v-else class="settings-page">
     <p class="status"><span class="dot"/>Configurações</p><h1>Credenciais e preferências</h1><p class="intro">Configure os serviços para testar o aplicativo. As chaves são salvas no Credential Manager do Windows.</p>
     <div class="section-head"><h2>API Keys dos serviços</h2></div>
     <div class="credentials">
      <form class="credential" @submit.prevent="saveA"><div class="service-copy"><h3>AssemblyAI</h3><p>Transcrição do áudio · {{settings.AssemblyAIConfigured?'Chave configurada':'Sem chave salva'}}</p></div><label class="sr-only" for="key-a">API Key AssemblyAI</label><div class="secret"><input id="key-a" v-model="keyA" :type="revealA?'text':'password'" autocomplete="off" spellcheck="false" placeholder="Insira uma nova API Key" :disabled="busy"><button type="button" :aria-label="revealA?'Ocultar API Key AssemblyAI':'Mostrar API Key AssemblyAI'" @click="revealA=!revealA">{{revealA?'Ocultar':'Ver'}}</button></div><div class="credential-actions"><button class="button" type="button" :disabled="busy||!settings.AssemblyAIConfigured" @click="studio.removeKey('assemblyai')">Remover</button><button class="button primary" type="submit" :disabled="busy||!keyA.trim()">Salvar</button></div></form>
      <form class="credential" @submit.prevent="saveD"><div class="service-copy"><h3>DeepSeek</h3><p>Revisão do texto · {{settings.DeepSeekConfigured?'Chave configurada':'Sem chave salva'}}</p></div><label class="sr-only" for="key-d">API Key DeepSeek</label><div class="secret"><input id="key-d" v-model="keyD" :type="revealD?'text':'password'" autocomplete="off" spellcheck="false" placeholder="Insira uma nova API Key" :disabled="busy"><button type="button" :aria-label="revealD?'Ocultar API Key DeepSeek':'Mostrar API Key DeepSeek'" @click="revealD=!revealD">{{revealD?'Ocultar':'Ver'}}</button></div><div class="credential-actions"><button class="button" type="button" :disabled="busy||!settings.DeepSeekConfigured" @click="studio.removeKey('deepseek')">Remover</button><button class="button primary" type="submit" :disabled="busy||!keyD.trim()">Salvar</button></div></form>
     </div>
     <section class="section"><h2>Modelo de revisão</h2><div class="choices"><label v-for="model in ['deepseek-flash','deepseek-v4-pro']" :key="model" class="choice"><input type="radio" name="model" :value="model" :checked="settings.Model===model" :disabled="busy" @change="studio.model(model)"><span><strong>{{model}}</strong><p>{{model==='deepseek-flash'?'Modelo padrão do aplicativo.':'Modelo alternativo; consulte preços da sua conta.'}}</p></span></label></div></section>
     <section class="section"><h2>Tema da interface</h2><div class="choices"><label v-for="value in (['light','dark'] as const)" :key="value" class="choice"><input v-model="theme" type="radio" name="theme" :value="value"><img :src="`/design/${value}-preview.png`" alt="" width="90" height="60"><strong>{{value==='light'?'Claro':'Escuro'}}</strong></label></div></section>
     <div class="notice">As chaves salvas nunca são exibidas novamente. Remova-as aqui antes de desinstalar, se desejar. Modelo e tema valem para a sessão atual.</div>
    </section>
   </div>
   <aside class="copilot session-panel" aria-label="Informações da sessão">
    <template v-if="page==='settings'"><img class="settings-art" src="/design/settings-illustration.png" alt=""><h2>Seu documento continua aqui</h2><p>Volte ao depoimento para continuar. Configurar uma chave não autoriza envio: cada arquivo exige confirmação separada por provedor.</p><button class="button" @click="navigate('document')">Voltar ao documento</button></template>
    <template v-else><h2>Seu espaço de trabalho</h2><p>Um arquivo por vez, com transcrição original, proposta e edição humana separadas.</p><h3 class="section-title">Configurações</h3><div class="action-box"><button class="action-row" @click="navigate('settings')"><span class="action-copy"><b>API Keys</b><small>AssemblyAI · {{settings.AssemblyAIConfigured?'configurada':'pendente'}}<br>DeepSeek · {{settings.DeepSeekConfigured?'configurada':'pendente'}}</small></span><span aria-hidden="true">›</span></button></div><h3 class="section-title">Ações do documento</h3><div class="action-box"><button class="action-row" :disabled="busy||state!=='ready'" @click="studio.copy"><span class="action-copy"><b>Copiar proposta</b><small>Inclui suas edições humanas</small></span></button><button class="action-row" :disabled="busy||state!=='ready'" @click="studio.exportText"><span class="action-copy"><b>Exportar TXT</b><small>Texto UTF-8 no destino escolhido</small></span></button></div><div class="tip"><div><h3>Preserve o sentido</h3><p>Perguntas não completam respostas. Incertezas, negações e relatos de terceiros precisam continuar explícitos.</p></div></div><section v-if="view?.RemoteID" class="remote"><h3>Registro na AssemblyAI</h3><code>{{view.RemoteID}}</code><p>{{view.RemoteDeleted?'A API confirmou a solicitação de exclusão.':'O registro remoto não é excluído ao cancelar ou fechar o app.'}}</p><button v-if="!view.RemoteDeleted" class="button danger" :disabled="busy" @click="studio.deleteRemote">Solicitar exclusão remota</button><button v-if="!view.RemoteDeleted" class="button" :disabled="busy" @click="studio.keepRemote">Manter remoto e liberar troca</button><small>Retenção de uploads, backups e outros artefatos depende das condições do provedor.</small></section></template>
   </aside>
  </main>
 </div>
</template>
